function artwork(kind) {
  const start = '<svg viewBox="0 0 600 330" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">';
  const end = '</svg>';
  if (kind === 'heritage') return start + `<rect width="600" height="330" fill="#233e35"/><g stroke="#75927b" opacity=".42" fill="none"><path d="M60 90 210 55 325 145 485 70M210 55 180 220 325 145 430 250 485 70M180 220 70 270M325 145 555 200M430 250 555 200M60 90 180 220"/><circle cx="325" cy="145" r="68" stroke-dasharray="3 6"/><circle cx="325" cy="145" r="106" opacity=".4"/></g><g fill="#c7d6bd"><circle cx="60" cy="90" r="4"/><circle cx="210" cy="55" r="6"/><circle cx="180" cy="220" r="7"/><circle cx="430" cy="250" r="5"/><circle cx="485" cy="70" r="5"/><circle cx="555" cy="200" r="4"/><circle cx="70" cy="270" r="4"/></g><g transform="translate(255 91) rotate(-5)"><rect x="8" y="8" width="132" height="131" rx="5" fill="#0d2c23"/><rect width="132" height="131" rx="5" fill="#f0e8d4"/><path d="m19 34 47-19 47 19M23 37h86M25 100h83M20 108h92M32 43v49m22-49v49m22-49v49m22-49v49" fill="none" stroke="#6f795e" stroke-width="2"/><text x="66" y="122" text-anchor="middle" fill="#6d755e" font-size="6" letter-spacing="1.3" font-family="Arial">CULTURAL HERITAGE</text></g><g font-family="Arial" fill="#cedac7"><text x="64" y="76" font-size="8">PEOPLE</text><text x="198" y="40" font-size="8">LEGISLATION</text><text x="107" y="241" font-size="8">HISTORICAL PRESS</text><text x="445" y="55" font-size="8">PLACES</text><text x="443" y="272" font-size="8">EVENTS</text></g><rect x="31" y="23" width="83" height="20" rx="10" fill="#ffffff12"/><text x="72" y="36" fill="#c8d7bc" font-size="7" text-anchor="middle" font-family="Arial" letter-spacing="1">CONNECTED HISTORY</text>` + end;
  if (kind === 'blood') return start + `<rect width="600" height="330" fill="#f0e3dc"/><circle cx="460" cy="110" r="150" fill="#e8d4ca"/><g stroke="#d6bbae" fill="none" opacity=".7"><circle cx="300" cy="160" r="120"/><circle cx="300" cy="160" r="94"/></g><g transform="translate(155 54) rotate(-4 140 100)"><rect x="7" y="8" width="290" height="202" rx="10" fill="#d9c3b5"/><rect width="290" height="202" rx="10" fill="#fffcf7"/><path d="M0 40h290" stroke="#eee2d8"/><circle cx="22" cy="21" r="8" fill="#b55e50"/><path d="m22 15-4 7a4 4 0 0 0 8 0Z" fill="#fff"/><text x="38" y="24" font-size="9" font-family="Arial" fill="#7e5146">Donation assistant</text><rect x="217" y="13" width="57" height="16" rx="8" fill="#f0e7df"/><text x="245" y="24" text-anchor="middle" font-size="7" font-family="Arial" fill="#916557">EN / ES</text><rect x="80" y="57" width="190" height="31" rx="7" fill="#f2e6db"/><text x="92" y="76" font-family="Arial" font-size="9" fill="#805b4f">Where can I learn about donating?</text><rect x="20" y="104" width="234" height="56" rx="7" fill="#f5f5ec"/><path d="M34 119h192m-192 10h173m-173 10h109" stroke="#c6ccbb" stroke-width="3"/><rect x="33" y="145" width="62" height="8" rx="4" fill="#d7e0ca"/><rect x="20" y="175" width="250" height="16" rx="8" fill="#f4eee6"/></g>` + end;
  if (kind === 'earth') {
    let tiles = ''; const palette = ['#244936','#3c6542','#527348','#6a864c','#8c9d63','#b1ae71','#c9b889','#8b9d73'];
    for (let row=0;row<12;row++) for(let col=0;col<21;col++){const n=(col*7+row*13+Math.floor(col/3)*row)%palette.length;tiles+=`<rect x="${col*30}" y="${row*30}" width="31" height="31" fill="${palette[n]}"/>`;}
    return start+`<rect width="600" height="330" fill="#3a6143"/><g opacity=".85">${tiles}</g><path d="M-30 290Q150 280 220 180T410 90 650 10" fill="none" stroke="#a2b6b6" stroke-width="18"/><path d="M-30 290Q150 280 220 180T410 90 650 10" fill="none" stroke="#d8e0cf" stroke-width="3" opacity=".6"/><path d="m128 56 201-21 124 78-33 128-190 38-136-96Z" fill="#ffffff0b" stroke="#e9e5bc" stroke-width="2" stroke-dasharray="7 4"/><g transform="translate(32 28)"><rect width="153" height="56" rx="5" fill="#f8f5e9"/><circle cx="17" cy="18" r="3" fill="#426848"/><text x="28" y="21" font-size="8" font-family="Arial" fill="#455b3d" letter-spacing="1">LAND-USE CLASSIFICATION</text><text x="15" y="40" font-size="8" font-family="Arial" fill="#7c836b">GeoJSON → satellite data → insight</text></g><g transform="translate(404 210)"><rect width="164" height="66" rx="5" fill="#f8f5e9"/><g font-family="Arial" font-size="7" fill="#586346"><rect x="14" y="13" width="8" height="8" fill="#244936"/><text x="29" y="20">Forestland</text><rect x="14" y="27" width="8" height="8" fill="#b1ae71"/><text x="29" y="34">Cropland</text><rect x="14" y="41" width="8" height="8" fill="#8c9d63"/><text x="29" y="48">Grassland</text><rect x="91" y="13" width="8" height="8" fill="#a2b6b6"/><text x="106" y="20">Wetland</text></g></g>`+end;
  }
  if(kind === 'maps'){
    let contours='';for(let i=0;i<12;i++){contours+=`<ellipse cx="440" cy="155" rx="${43+i*16}" ry="${21+i*12}" transform="rotate(-24 440 155)" fill="none" stroke="#bac3a7" stroke-width=".8"/>`;}
    return start+`<rect width="600" height="330" fill="#e4e7d9"/>${contours}<path d="M0 240Q135 100 240 210T490 240 650 60" fill="none" stroke="#a6bbbd" stroke-width="10"/><path d="M0 240Q135 100 240 210T490 240 650 60" fill="none" stroke="#d8e3df" stroke-width="3"/><g transform="translate(62 49) rotate(-7 110 100)"><rect x="6" y="7" width="208" height="211" rx="3" fill="#c6cdbb"/><rect width="208" height="211" rx="3" fill="#f4edda"/><path d="M16 30h174M16 180h174" stroke="#c9bf9d"/><g stroke="#cfc4a4" fill="none"><path d="M20 70q50-30 80 0t85-15M20 82q50-30 80 0t85-15M20 95q50-30 80 0t85-15M20 108q50-30 80 0t85-15M20 120q50-30 80 0t85-15M20 135q50-30 80 0t85-15"/></g><path d="M110 36q-50 40-15 85t-35 57" fill="none" stroke="#8faead" stroke-width="4"/><text x="104" y="20" text-anchor="middle" font-family="Georgia" font-size="8" fill="#8a8061">WATER RESOURCES ARCHIVE</text><text x="104" y="197" text-anchor="middle" font-family="Arial" font-size="7" fill="#8a8061" letter-spacing="1">HISTORICAL MAP · TIFF</text></g><g transform="translate(337 114)"><rect width="183" height="91" rx="6" fill="#fffdf5"/><text x="16" y="23" font-family="monospace" font-size="8" fill="#486749">{ "type": "Feature",</text><text x="24" y="40" font-family="monospace" font-size="8" fill="#8b977a">"geometry": { ... },</text><text x="24" y="57" font-family="monospace" font-size="8" fill="#8b977a">"properties": { ... }</text><text x="16" y="75" font-family="monospace" font-size="8" fill="#486749">}</text></g><path d="M278 149h46m-6-5 6 5-6 5" stroke="#6a805f" fill="none"/>`+end;
  }
  if(kind === 'charities') return start+`<rect width="600" height="330" fill="#e7dfd5"/><circle cx="300" cy="160" r="126" fill="#ded3c4"/><path d="M100 92h130l60 70 80-71h130M97 245h143l50-83 80 75h130" stroke="#c2b49f" stroke-dasharray="4 5" fill="none"/><g transform="translate(230 92)"><rect x="6" y="7" width="140" height="140" rx="20" fill="#c9b99f"/><rect width="140" height="140" rx="20" fill="#fbf8ee"/><path d="m42 56 28-21 28 21v43H42Z" fill="none" stroke="#9d8c72" stroke-width="2"/><path d="M63 99V77h14v22" fill="none" stroke="#9d8c72" stroke-width="2"/><path d="M51 65h8m22 0h8" stroke="#9d8c72" stroke-width="3"/><text x="70" y="120" text-anchor="middle" font-family="Arial" font-size="7" letter-spacing="1" fill="#8b7a64">FINDING SUPPORT</text></g><g font-family="Arial" font-size="9" fill="#867660"><rect x="60" y="70" width="140" height="40" rx="5" fill="#f6f2e8"/><text x="80" y="94">Housing assistance</text><rect x="393" y="70" width="140" height="40" rx="5" fill="#f6f2e8"/><text x="415" y="94">Food assistance</text><rect x="60" y="220" width="140" height="40" rx="5" fill="#f6f2e8"/><text x="80" y="244">Local connections</text><rect x="393" y="220" width="140" height="40" rx="5" fill="#f6f2e8"/><text x="415" y="244">Disaster support</text></g>`+end;
  if(kind === 'compiler') return start+`<rect width="600" height="330" fill="#28332f"/><g opacity=".15" stroke="#91a18b"><path d="M0 60h600M0 120h600M0 180h600M0 240h600M0 300h600M60 0v330M120 0v330M180 0v330M240 0v330M300 0v330M360 0v330M420 0v330M480 0v330M540 0v330"/></g><g transform="translate(70 55)"><rect width="275" height="207" rx="7" fill="#1d2823" stroke="#445746"/><circle cx="18" cy="18" r="3" fill="#d59470"/><circle cx="31" cy="18" r="3" fill="#b4ad7a"/><circle cx="44" cy="18" r="3" fill="#7d9a72"/><g font-family="monospace" font-size="12"><text x="22" y="62" fill="#dda583">POLY</text><text x="22" y="87" fill="#d9e1c7">  F(x) = x² + 2x;</text><text x="22" y="123" fill="#dda583">EXECUTE</text><text x="22" y="148" fill="#d9e1c7">  a = F(3);</text><text x="22" y="173" fill="#d9e1c7">  OUTPUT a;</text></g></g><path d="M367 163h42m-6-5 6 5-6 5" stroke="#a8b798" fill="none"/><g transform="translate(428 95)" stroke="#8ca17b" fill="none"><path d="M40 25v30M40 55 10 85m30-30 30 30M10 100v28m60-28v28"/><g fill="#3b503e"><rect x="20" width="40" height="27" rx="4"/><rect y="78" width="25" height="25" rx="4"/><rect x="58" y="78" width="25" height="25" rx="4"/><circle cx="10" cy="137" r="9"/><circle cx="70" cy="137" r="9"/></g></g>`+end;
  return start+`<rect width="600" height="330" fill="#dce5e7"/><g opacity=".7" stroke="#becfd2" fill="none"><path d="M0 110h600M0 220h600M100 0v330M200 0v330M300 0v330M400 0v330M500 0v330"/></g><g transform="translate(85 65) rotate(-3)"><rect x="5" y="6" width="170" height="191" rx="6" fill="#b9cbce"/><rect width="170" height="191" rx="6" fill="#f7f8f1"/><rect width="170" height="34" rx="6" fill="#5a7d7b"/><text x="15" y="22" fill="#fff" font-family="monospace" font-size="10">bookings</text><g fill="#6b7c75" font-family="monospace" font-size="9"><text x="16" y="61">PK  booking_id</text><text x="16" y="89">FK  customer_id</text><text x="16" y="117">FK  tour_id</text><text x="16" y="145">    total_amount</text><text x="16" y="172">    status</text></g></g><path d="M265 119h70v-14h25M265 206h70v19h25" fill="none" stroke="#799a96" stroke-width="1.5"/><g transform="translate(360 56)"><rect width="153" height="94" rx="5" fill="#f7f8f1"/><rect width="153" height="29" rx="5" fill="#76918b"/><text x="14" y="20" fill="#fff" font-family="monospace" font-size="10">customers</text><text x="14" y="54" fill="#6b7c75" font-family="monospace" font-size="9">PK  customer_id</text><text x="14" y="77" fill="#6b7c75" font-family="monospace" font-size="9">    name</text></g><g transform="translate(360 185)"><rect width="153" height="94" rx="5" fill="#f7f8f1"/><rect width="153" height="29" rx="5" fill="#76918b"/><text x="14" y="20" fill="#fff" font-family="monospace" font-size="10">tours</text><text x="14" y="54" fill="#6b7c75" font-family="monospace" font-size="9">PK  tour_id</text><text x="14" y="77" fill="#6b7c75" font-family="monospace" font-size="9">    destination</text></g>`+end;
}


window.portfolioArtwork = artwork;
